-- Run on a NEW Supabase project using the SQL editor. Review before use.
create schema if not exists private;
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade);
alter table public.admin_users enable row level security;
create policy "admins see own membership" on public.admin_users for select to authenticated using (user_id = (select auth.uid()));
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())); $$;
revoke all on function private.is_admin() from public;
grant usage on schema private to authenticated;
grant execute on function private.is_admin() to authenticated;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text default '', phone text default '', created_at timestamptz default now());
create table if not exists public.services (id bigint generated by default as identity primary key, name text not null, description text default '', price numeric not null check (price >= 0), image_url text default '', is_active boolean default true, created_at timestamptz default now());
create table if not exists public.gallery (id bigint generated by default as identity primary key, title text not null, description text default '', image_url text not null, category text default '', display_order int default 0, created_at timestamptz default now());
create table if not exists public.testimonials (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, customer_name text not null check (char_length(customer_name) between 1 and 80), review text not null check (char_length(review) between 10 and 2000), rating int not null check (rating between 1 and 5), is_approved boolean not null default false, created_at timestamptz default now());
create table if not exists public.site_settings (id bigint generated by default as identity primary key, setting_key text unique not null, setting_value text not null, updated_at timestamptz default now());
alter table public.profiles enable row level security;
alter table public.services enable row level security;
alter table public.gallery enable row level security;
alter table public.testimonials enable row level security;
alter table public.site_settings enable row level security;
grant select on public.services, public.gallery, public.testimonials, public.site_settings to anon, authenticated;
grant select, insert, update, delete on public.profiles, public.services, public.gallery, public.testimonials, public.site_settings to authenticated;
grant select on public.admin_users to authenticated;
grant usage, select on all sequences in schema public to authenticated;
create policy "profile read own or admin" on public.profiles for select to authenticated using (id=(select auth.uid()) or (select private.is_admin()));
create policy "profile insert own" on public.profiles for insert to authenticated with check (id=(select auth.uid()));
create policy "profile update own" on public.profiles for update to authenticated using (id=(select auth.uid())) with check (id=(select auth.uid()));
create policy "public active services" on public.services for select to anon, authenticated using (is_active=true);
create policy "admin services" on public.services for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "public gallery" on public.gallery for select to anon, authenticated using (true);
create policy "admin gallery" on public.gallery for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "public approved testimonials" on public.testimonials for select to anon, authenticated using (is_approved=true);
create policy "submit own unapproved testimonial" on public.testimonials for insert to authenticated with check (user_id=(select auth.uid()) and is_approved=false);
create policy "admin testimonials" on public.testimonials for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy "public site text" on public.site_settings for select to anon, authenticated using (setting_key in ('home_description','about_description'));
create policy "admin settings" on public.site_settings for all to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
