insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('welly-media','welly-media',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy "public media read" on storage.objects for select to anon, authenticated using (bucket_id='welly-media');
create policy "admin media insert" on storage.objects for insert to authenticated with check (bucket_id='welly-media' and (select private.is_admin()));
create policy "admin media update" on storage.objects for update to authenticated using (bucket_id='welly-media' and (select private.is_admin())) with check (bucket_id='welly-media' and (select private.is_admin()));
create policy "admin media delete" on storage.objects for delete to authenticated using (bucket_id='welly-media' and (select private.is_admin()));
